$[Error] var_set name="color" value={var count | if condition={eq 0} then={var color_grey} else={var color_red}} 
| var_set name=val value={var value_invisible | if condition={eq true} then="" else={var count}} 
| markdown  "[" {var val} "](" {var url} ") " 
| render 
  css={string ".canvasRenderEl {
 position: relative;
}

.canvasRenderEl a {
  background-color: " {var "color"} ";
  display: " {var ComponentsLength | if condition={lte {var ComponentsIndex}} then=none else=block} ";
  margin: 20px;
padding-top: 12px;
  position: absolute;
  top: 0;
  bottom: 0;
  right: 0;
  left: 0;
  opacity: 1;
  vertical-align: center;
border-radius: 4px;
line-height: 20px;
text-align: center;
font-size: 20px;
text-decoration: none;
box-shadow: 0 2px 2px rgba(0,0,0,0.2);
color: #FFFFFF;
}

.canvasRenderEl a:after {
content: '" {var    label_red_box} "';
font-size: 14px;
display: block;
}"

{var count | if condition={gt 0} then={string "
.canvasRenderEl a:hover {
  background-color: #ff0000;
  transition: all .25s;
}"}}
}

